const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function request(path,body){const r=await fetch(path,{credentials:'include',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});if(!r.ok||r.redirected)throw Error('Unexpected server response '+r.status);return r.json();}
async function identity(){const j=await request('/api/v1/auths/');if(j.role==='guest'&&j.idp==='z.ai')return null;if(j.role==='user'&&typeof j.id==='string'&&j.id)return j;throw Error('Unknown session response');}
async function ready(fn,ms=7000){const end=Date.now()+ms;do{const v=fn();if(v)return v;await sleep(150);}while(Date.now()<end);throw Error('Z.ai interface not ready');}
const currentId=()=>location.pathname.match(/^\/c\/([A-Za-z0-9-]+)$/)?.[1]||null;
async function detail(id){const j=await request('/api/v1/chats/'+encodeURIComponent(id));if(j.id!==id||!j.chat?.history?.messages)throw Error('Conversation mismatch');const h=j.chat.history;const ids=[];const seen=new Set();let p=h.currentId;while(p&&ids.length<100){if(seen.has(p)||!h.messages[p])throw Error('Invalid message branch');seen.add(p);ids.unshift(p);p=h.messages[p].parentId;}let data={};if(ids.length){const b=await request('/api/v1/chats/'+encodeURIComponent(id)+'/messages/batch',{ids});if(b.chat_id!==id||!b.data)throw Error('Message batch mismatch');data=b.data;}return {conversationId:id,title:String(j.title||''),url:'https://chat.z.ai/c/'+id,messages:ids.map(k=>{const x=data[k];if(!x||x.chat_id!==id)throw Error('Missing message');return {id:k,role:String(x.role),text:typeof x.content==='string'?x.content:(x.content_blocks||[]).filter(v=>v.type==='text').map(v=>v.content||'').join(''),done:x.done===true};}),truncated:!!p};}
async function open(id){const d=await detail(id);let editor=await ready(()=>document.querySelector('textarea#chat-input'));if(editor.value.trim())throw Error('Existing draft must be preserved');if(currentId()!==id){const find=()=>[...document.querySelectorAll('button[data-selected]')].filter(x=>x.innerText.trim()===d.title);if(!find().length)document.querySelector('#sidebar-toggle-button')?.click();const b=await ready(()=>{const a=find();if(a.length>1)throw Error('Ambiguous sidebar title');return a[0];});b.click();await ready(()=>currentId()===id&&document.querySelector('textarea#chat-input'));}return detail(id);}
async function send(message,target){let baseline=[];if(target){const d=await open(target);baseline=d.messages.map(x=>x.id);}else{let e=await ready(()=>document.querySelector('textarea#chat-input'));if(e.value.trim())throw Error('Existing draft must be preserved');if(currentId()){const b=document.querySelector('#new-chat-button');if(!b)throw Error('New chat unavailable');b.click();await ready(()=>location.pathname==='/');}}
const e=await ready(()=>document.querySelector('textarea#chat-input'));if(e.value.trim())throw Error('Existing draft must be preserved');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,message);e.dispatchEvent(new Event('input',{bubbles:true}));const b=await ready(()=>{const x=document.querySelector('#send-message-button');return x&&!x.disabled&&e.value===message?x:null;},2500);if(target&&currentId()!==target)throw Error('Conversation changed');b.click();const end=Date.now()+12000;let confirmed=false,reply=null,id=null;do{await sleep(650);id=currentId();if(!id||(target&&id!==target))continue;const d=await detail(id);const fresh=d.messages.filter(x=>!baseline.includes(x.id));const u=fresh.find(x=>x.role==='user'&&x.text===message);if(u){confirmed=true;const a=fresh.slice(fresh.indexOf(u)+1).find(x=>x.role==='assistant');if(a?.text)reply=a.text;if(a?.done)return {status:'completed',submissionConfirmed:true,url:d.url,conversationId:id,reply};}}while(Date.now()<end);return {status:confirmed?'accepted':'pending',submissionConfirmed:confirmed,url:location.href,conversationId:id,reply};}

const nativeHistoryPages=new Map();
if(typeof window!=='undefined'&&typeof window.fetch==='function'){const originalFetch=window.fetch;window.fetch=function(input,init){let page=null;try{const u=new URL(typeof input==='string'?input:input.url,location.href);if(u.origin===location.origin&&u.pathname==='/api/v1/chats/'&&u.searchParams.get('type')==='default'&&init?.headers)page=u.searchParams.get('page');}catch{}return originalFetch.apply(this,arguments).then(response=>{if(page)response.clone().json().then(data=>{if(!response.ok||!Array.isArray(data)||data.some(x=>typeof x.id!=='string'||typeof x.title!=='string')){nativeHistoryPages.set(page,{error:'Unexpected native Z.ai history response'});return;}nativeHistoryPages.set(page,{items:data.map(x=>({id:x.id,title:x.title,url:'https://chat.z.ai/c/'+encodeURIComponent(x.id)}))});while(nativeHistoryPages.size>20)nativeHistoryPages.delete(nativeHistoryPages.keys().next().value);}).catch(()=>nativeHistoryPages.set(page,{error:'Unable to read native Z.ai history response'}));return response;});};}
async function searchTitles({query,cursor='1'}){if(!query.trim())throw Error('Search query must not be blank');const page=Number(cursor);if(!Number.isSafeInteger(page)||page<1)throw Error('Invalid history cursor');await ready(()=>nativeHistoryPages.has('1'),10000);if(!nativeHistoryPages.has(cursor)){const pages=[...nativeHistoryPages.keys()].map(Number);if(page!==Math.max(...pages)+1)throw Error('History page is not loaded; restart and continue sequentially');const sidebar=document.querySelector('#sidebar');if(!sidebar)throw Error('History sidebar unavailable');const scrollers=[sidebar,...sidebar.querySelectorAll('*')].filter(e=>e.clientHeight>100&&e.scrollHeight>e.clientHeight+20&&['auto','scroll'].includes(getComputedStyle(e).overflowY));if(!scrollers.length)throw Error('Native history continuation is not available');for(const e of scrollers){e.scrollTop=e.scrollHeight;e.dispatchEvent(new Event('scroll'));}await ready(()=>nativeHistoryPages.has(cursor),8000);}const data=nativeHistoryPages.get(cursor);if(data.error)throw Error(data.error);const q=query.trim().toLocaleLowerCase();return {items:data.items.filter(x=>x.title.toLocaleLowerCase().includes(q)),nextCursor:data.items.length?String(page+1):null,scope:'default-history-titles'};}

window.ox.install(({action})=>{
action('searchConversations',{invoke:searchTitles});
action('getSignInUrl',{async invoke(){return {url:'https://chat.z.ai/'};}});
action('getSignInState',{async invoke(){return {signedIn:!!await identity()};}});
action('getCurrentUser',{async invoke(){const j=await identity();if(!j)throw Error('Sign in required');return {id:j.id,name:String(j.name||''),email:String(j.email||'')};}});
action('listModels',{async invoke(){const j=await request('/api/models');if(!Array.isArray(j.data))throw Error('Invalid models response');return {items:j.data.map(x=>({id:String(x.id),name:String(x.name)})),nextCursor:null};}});
action('listConversations',{async invoke({cursor}){const page=Number(cursor||'1');const j=await request('/api/v1/chats/?page='+page+'&type=default');if(!Array.isArray(j))throw Error('Invalid chat list');return {items:j.map(x=>({id:String(x.id),title:String(x.title),url:'https://chat.z.ai/c/'+x.id})),nextCursor:j.length?String(page+1):null};}});
action('getConversation',{async invoke({conversationId}){return detail(conversationId);}});
action('openConversation',{async invoke({conversationId}){return open(conversationId);}});
action('chat',{async invoke({message}){return send(message,null);}});
action('continueChat',{async invoke({conversationId,message}){return send(message,conversationId);}});
});